/**
 * Sub-issue tree rules that need no I/O: the placement check behind `setIssueParent` and issue creation.
 *
 * The service layer loads the parent's ancestor chain and the moved subtree's height, then asks this module whether the placement is legal.
 */
import { MAX_SUB_ISSUE_DEPTH } from "@/config/constants";
import type { IssueId } from "@/types/common";

/** Raised when a parent change would loop the tree or push a descendant past `MAX_SUB_ISSUE_DEPTH`. */
export class IssueHierarchyError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: string,
    readonly reason: "cycle" | "too_deep",
  ) {
    super(
      reason === "cycle"
        ? `Issue ${issueId} cannot be placed under itself or its own sub-issues`
        : `Issue ${issueId} cannot be placed: sub-issues would sit deeper than level ${MAX_SUB_ISSUE_DEPTH}`,
    );
    this.name = "IssueHierarchyError";
  }
}

/**
 * Throws unless `issueId` (with `subtreeHeight` levels of sub-issues below it) may sit under the parent described by `parentChain`.
 *
 * @param parentChain the new parent followed by its ancestors, nearest first; its length is the level the issue would take
 * @param subtreeHeight how many levels sit below the issue (0 for a leaf)
 */
export function assertPlacement(
  issueId: IssueId,
  parentChain: readonly IssueId[],
  subtreeHeight: number,
): void {
  if (parentChain.includes(issueId)) {
    throw new IssueHierarchyError(issueId, "cycle");
  }

  const deepest = parentChain.length + subtreeHeight;
  if (deepest > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(issueId, "too_deep");
  }
}
