/**
 * Places an issue under a live parent of its own project, or makes it a root
 * issue again with `null`. The sub-issues below it move with it, so the depth
 * check is judged by the deepest of them. Refused moves change nothing.
 */
export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  if (input.parentId !== null) {
    await requireLiveParent(input.orgId, before.projectId, input.parentId);
  }

  if (input.parentId === before.parentId) return before;

  if (input.parentId !== null) {
    assertPlacement(
      before.id,
      await parentChain(input.orgId, input.parentId),
      subtreeHeight(await loadSubtree(input.orgId, before.id)),
    );
  }

  const after = await issueRepo.setIssueParent(
    input.orgId,
    input.issueId,
    input.parentId,
  );

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: ["parentId"],
  });

  return after;
}

/** Direct sub-issues that are not archived, oldest first. */
export async function listSubIssues(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return issueRepo.listChildIssues(orgId, [issue.id]);
}

/** Counts over every live issue below `issueId`, at any depth. */
export async function getIssueRollup(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const live = (await loadSubtree(orgId, issue.id))
    .map((node) => node.issue)
    .filter((node) => node.archivedAt === null);
  const open = live.filter((node) => isOpen(node)).length;

  return { total: live.length, open, closed: live.length - open };
}

