import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import { subscribe } from "@/lib/event-bus";
import * as issueService from "@/server/services/issue-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import { TenantScopeError } from "@/lib/tenant";
import { IssueHierarchyError } from "@/lib/issue-hierarchy";
import { toAppError } from "@/lib/errors";

let cleanup: () => void;
let t: Tenant;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); t = await createTenant("scratchsub"); });
afterAll(() => cleanup());

const mk = (title: string, parentId: string | null = null, extra: Record<string, unknown> = {}) =>
  issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title, parentId, ...extra }) as never);

describe("scratch", () => {
  it("tree behaviour", async () => {
    const a = await mk("Alpha root");
    const b = await mk("Beta child", a.id);
    const c = await mk("Gamma grandchild", b.id);
    const d = await mk("Delta great", c.id);
    await expect(mk("Too deep leaf", d.id)).rejects.toBeInstanceOf(IssueHierarchyError);
    const e = await mk("Eps root");
    await expect(issueService.setIssueParent(t.actors.member, { orgId: t.org.id, issueId: a.id, parentId: d.id } as never)).rejects.toMatchObject({ reason: "cycle" });
    await expect(issueService.setIssueParent(t.actors.member, { orgId: t.org.id, issueId: a.id, parentId: a.id } as never)).rejects.toMatchObject({ reason: "cycle" });
    await expect(issueService.setIssueParent(t.actors.member, { orgId: t.org.id, issueId: e.id, parentId: c.id } as never)).rejects.toMatchObject({ reason: "too_deep" });
    expect((await issueService.getIssueRollup(t.actors.member, t.org.id, a.id))).toEqual({ total: 3, open: 3, closed: 0 });
    const moved = await issueService.setIssueParent(t.actors.member, { orgId: t.org.id, issueId: e.id, parentId: a.id } as never).catch((x) => x);
    expect(moved).toBeInstanceOf(IssueHierarchyError); // a's subtree height 3 => too deep
    const kids = await issueService.listSubIssues(t.actors.member, t.org.id, a.id);
    expect(kids.map((k) => k.id)).toEqual([b.id]);
    await expect(issueService.listSubIssues(t.actors.member, t.org.id, b.id).then((x) => x.length)).resolves.toBe(1);
    const err = toAppError(new IssueHierarchyError("x", "cycle"));
    expect(err.code).toBe("conflict");
    const other = await createTenant("scratchsubo");
    await expect(issueService.listSubIssues(other.actors.member, t.org.id, a.id)).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("archive cascade and completion notice", async () => {
    const p = await mk("Parent assigned", null, { assigneeId: t.userIds.member });
    const k1 = await mk("Kid one", p.id);
    const k2 = await mk("Kid two", p.id);
    const archived: string[] = [];
    const notices: unknown[] = [];
    const off1 = subscribe("issue.archived", (x) => { archived.push(x.issueId); });
    const off2 = subscribe("issue.sub_issues_completed", (x) => { notices.push(x); });
    try {
      await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: k1.id, status: "done" } as never);
      expect(notices).toHaveLength(0);
      await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: k2.id, status: "canceled" } as never);
      expect(notices).toHaveLength(1);
      await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: k2.id, status: "todo" } as never);
      await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: k2.id, status: "done" } as never);
      expect(notices).toHaveLength(2);
      await issueService.archiveIssue(t.actors.member, t.org.id, p.id);
      expect(archived).toEqual([p.id, k1.id, k2.id]);
    } finally { off1(); off2(); }
  });
});
EOF
